using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Reflection;
using LastRail.Auth;
using LastRail.Run;
using LastRail.Diagnostics;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class RunCompleteClaimReceiptTests {
  // Preserve the original file; only the test request key is adapted to the existing client >=16-character subset.
  static JObject Fixture(){var p=(JObject)LastRail.Auth.GameApiJson.ReadObject(File.ReadAllText(Path.GetFullPath("../QA/CommanderS1-20260922/run-complete-claim-example-20261019.json")))["response"];p["commandId"]="unity-fixture-complete-key";return p;}
  static PendingRunOperation Operation(JObject p)=>PendingRunOperation.Claim((string)p["accountId"],RunRewardClaimRequest.Create((string)p["runId"],(string)p["rewardPreviewId"],(string)p["commandId"]),new AppBuildSnapshot(null,null),DateTimeOffset.UtcNow);
  static PendingRunOperation CompleteOperation(JObject p){var method=typeof(PendingRunOperation).GetMethod("CompleteClaim");Assert.That(method,Is.Not.Null,"Missing version-pinned complete claim request");return (PendingRunOperation)method.Invoke(null,new object[]{(string)p["accountId"],RunRewardClaimRequest.Create((string)p["runId"],(string)p["rewardPreviewId"],(string)p["commandId"]),new AppBuildSnapshot(null,null),DateTimeOffset.UtcNow});}
  // Synthetic size cases derived from the supplied fixture, not server executions.
  static string SizedFixture(int bytes,string payload="a") {var p=Fixture();p["transactionReceipt"]["rewardPlan"]["capacityFixture"]=string.Concat(Enumerable.Repeat(payload,90000));var json=p.ToString(Newtonsoft.Json.Formatting.None);Assert.That(Encoding.UTF8.GetByteCount(json),Is.LessThan(bytes));return json+new string(' ',bytes-Encoding.UTF8.GetByteCount(json));}
  [Test] public void CompleteReceiptAcceptsServerUtf8BoundaryAndRejectsOneByteOver(){var json=SizedFixture(512*1024);var p=Fixture();Assert.DoesNotThrow(()=>RunCompleteClaimReceipt.Read(json,(string)p["accountId"],(string)p["runId"],(string)p["rewardPreviewId"],(string)p["commandId"]));Assert.Throws<FormatException>(()=>RunCompleteClaimReceipt.Read(json+" ",(string)p["accountId"],(string)p["runId"],(string)p["rewardPreviewId"],(string)p["commandId"]));}
  [TestCase("a")][TestCase("한")][TestCase("\"")]
  public async Task PinnedLargeReceiptSurvivesJournalReconstruction(string payload){var p=Fixture();var json=SizedFixture(512*1024,payload);var op=CompleteOperation(p);var storage=(IAndroidKeystoreNativeStoragePort)Activator.CreateInstance(typeof(RunOperationJournalTests).GetNestedType("Native",BindingFlags.NonPublic),true);var journal=new EncryptedRunOperationJournal(storage);Assert.That(await journal.PutAsync(op),Is.True);Assert.That(await journal.ConfirmAsync(op,json),Is.True);var loaded=(await new EncryptedRunOperationJournal(storage).ReadAsync(op.AccountId)).Single();Assert.That(loaded.AcceptedResponseJson,Is.EqualTo(json));Assert.That(typeof(PendingRunOperation).GetProperty("ResponseVersion").GetValue(loaded),Is.EqualTo(RunCompleteClaimReceipt.Version));Assert.That(loaded.IdempotencyKey,Is.EqualTo(op.IdempotencyKey));}
  [Test] public async Task CompleteReservationRefusesSecondPendingBeforeChangingStoredRecords(){var p=Fixture();var storage=(IAndroidKeystoreNativeStoragePort)Activator.CreateInstance(typeof(RunOperationJournalTests).GetNestedType("Native",BindingFlags.NonPublic),true);var journal=new EncryptedRunOperationJournal(storage);for(int i=0;i<3;i++){p["runId"]="capacity_run_"+i;p["commandId"]="capacity_original_key_"+i;Assert.That(await journal.PutAsync(CompleteOperation(p)),Is.EqualTo(i<1));}Assert.That((await journal.ReadAsync((string)p["accountId"] )).Count,Is.EqualTo(1));}
  sealed class ClaimWire:IRunApiHttpTransport {
   public readonly System.Collections.Generic.List<RunApiHttpRequest> Requests=new System.Collections.Generic.List<RunApiHttpRequest>();
   public string Reply;public Task<RunApiHttpResponse> SendAsync(RunApiHttpRequest request){Requests.Add(request);return Task.FromResult(Reply==null?RunApiHttpResponse.NetworkError("Synthetic lost response"):RunApiHttpResponse.Success(200,Reply));}
  }
  static Task<PendingRunOperation> SubmitComplete(DurableRunClient client,JObject p){var method=typeof(DurableRunClient).GetMethod("ClaimCompleteAsync");Assert.That(method,Is.Not.Null,"Missing explicit complete-claim submission");return (Task<PendingRunOperation>)method.Invoke(client,new object[]{RunRewardClaimRequest.Create((string)p["runId"],(string)p["rewardPreviewId"],(string)p["commandId"])});}
  // Reversible encoding substitutes for Android Keystore in this desktop file-
  // boundary test; it is not cryptographic or device validation.
  sealed class FileTestCrypto:IAndroidKeystoreNativeStoragePort {
   public bool IsAndroidRuntime=>true;public bool IsKeystoreAvailable=>true;public bool UsedPlayerPrefsFallback=>false;public string ProviderName=>"fixture_base64_not_encryption";
   public AndroidKeystoreEncryptedTokenPayload Encrypt(string value)=>new AndroidKeystoreEncryptedTokenPayload(Convert.ToBase64String(Encoding.UTF8.GetBytes(value)),"fixture_iv");
   public string Decrypt(AndroidKeystoreEncryptedTokenPayload value)=>Encoding.UTF8.GetString(Convert.FromBase64String(value.CipherTextBase64));
   public bool Save(AndroidKeystoreEncryptedTokenPayload value)=>throw new InvalidOperationException();public AndroidKeystoreEncryptedTokenPayload Load()=>throw new InvalidOperationException();public bool Clear()=>throw new InvalidOperationException();
  }
  [Test] public async Task MaximumReceiptRestoresThroughActualRunFileAdapter(){var p=Fixture();var op=CompleteOperation(p);var path=Path.GetFullPath("../QA/OperatorInformation-20261019/ClaimCapacityFiles/"+Guid.NewGuid().ToString("N")+".json");var journal=new EncryptedRunOperationJournal(new AndroidEncryptedRunFilePort(new FileTestCrypto(),path));var json=SizedFixture(512*1024,"한");Assert.That(await journal.PutAsync(op),Is.True);Assert.That(await journal.ConfirmAsync(op,json),Is.True);var restored=await new EncryptedRunOperationJournal(new AndroidEncryptedRunFilePort(new FileTestCrypto(),path)).ReadAsync(op.AccountId);Assert.That(restored.Single().AcceptedResponseJson,Is.EqualTo(json));Assert.That(new FileInfo(path).Length,Is.LessThan(16*1024*1024));}
  [Test] public void Utf8LimitCannotBeBypassedWithShortMultibyteText(){var p=Fixture();p["transactionReceipt"]["rewardPlan"]["capacityFixture"]=new string('한',180000);var json=p.ToString(Newtonsoft.Json.Formatting.None);Assert.That(json.Length,Is.LessThan(262144));Assert.Throws<FormatException>(()=>RunCompleteClaimReceipt.Read(json,(string)p["accountId"],(string)p["runId"],(string)p["rewardPreviewId"],(string)p["commandId"]));}
  [Test] public async Task LiteralUnicodeNextLineStillFitsItsReservedConfirmation(){var p=Fixture();p["transactionReceipt"]["rewardPlan"]["capacityFixture"]=new string('\u0085',250000);var json=p.ToString(Newtonsoft.Json.Formatting.None).Replace("\\u0085","\u0085");Assert.That(Encoding.UTF8.GetByteCount(json),Is.LessThan(512*1024));Assert.That(new JValue(json).ToString(Newtonsoft.Json.Formatting.None).Length,Is.GreaterThan(2*512*1024+2));var op=CompleteOperation(p);Assert.DoesNotThrow(()=>op.Confirmed(json));var storage=(IAndroidKeystoreNativeStoragePort)Activator.CreateInstance(typeof(RunOperationJournalTests).GetNestedType("Native",BindingFlags.NonPublic),true);var journal=new EncryptedRunOperationJournal(storage);Assert.That(await journal.PutAsync(op),Is.True);Assert.That(await journal.ConfirmAsync(op,json),Is.True);Assert.That((await new EncryptedRunOperationJournal(storage).ReadAsync(op.AccountId)).Single().AcceptedResponseJson,Is.EqualTo(json));}
  [Test] public async Task ExhaustedCompleteReservationNeverSendsAndLegacyRequestIsNotUpgraded(){var p=Fixture();var storage=(IAndroidKeystoreNativeStoragePort)Activator.CreateInstance(typeof(RunOperationJournalTests).GetNestedType("Native",BindingFlags.NonPublic),true);var journal=new EncryptedRunOperationJournal(storage);var session=SupportInquiryTests.Session((string)p["accountId"]);var wire=new ClaimWire();using(var client=new DurableRunClient(new GameApiAuthenticatedHttpTransport(wire),journal,()=>session,()=>1)){for(int i=0;i<3;i++){p["runId"]="submission_run_"+i;p["commandId"]="submission_original_key_"+i;Assert.That(await SubmitComplete(client,p),Is.Null);}Assert.That(wire.Requests.Count,Is.EqualTo(1));}
   var legacy=Operation(Fixture());var other=(IAndroidKeystoreNativeStoragePort)Activator.CreateInstance(typeof(RunOperationJournalTests).GetNestedType("Native",BindingFlags.NonPublic),true);var legacyJournal=new EncryptedRunOperationJournal(other);await legacyJournal.PutAsync(legacy);wire.Requests.Clear();using(var client=new DurableRunClient(new GameApiAuthenticatedHttpTransport(wire),legacyJournal,()=>session,()=>1)){Assert.That(await SubmitComplete(client,Fixture()),Is.Null);Assert.That(wire.Requests,Is.Empty);Assert.That((await legacyJournal.ReadAsync(legacy.AccountId)).Single().ResponseVersion,Is.Null);}
  }
  [Test] public async Task RestartRetainsOptInHeaderAndOriginalRequestBeforeOneDurableConfirmation(){var p=Fixture();var op=CompleteOperation(p);var storage=(IAndroidKeystoreNativeStoragePort)Activator.CreateInstance(typeof(RunOperationJournalTests).GetNestedType("Native",BindingFlags.NonPublic),true);var journal=new EncryptedRunOperationJournal(storage);Assert.That(await journal.PutAsync(op),Is.True);var session=SupportInquiryTests.Session(op.AccountId);var wire=new ClaimWire();
   using(var client=new DurableRunClient(new GameApiAuthenticatedHttpTransport(wire),journal,()=>session,()=>1)){await client.RestoreAsync();Assert.That(await client.RetryAsync(client.Operations.Single()),Is.Null);}
   using(var client=new DurableRunClient(new GameApiAuthenticatedHttpTransport(wire),new EncryptedRunOperationJournal(storage),()=>session,()=>1)){await client.RestoreAsync();wire.Reply=SizedFixture(512*1024);var receipt=await client.RetryAsync(client.Operations.Single());Assert.That(receipt,Is.Not.Null,client.Notice);await client.RetryAsync(receipt);}
   Assert.That(wire.Requests.Count,Is.EqualTo(2));foreach(var request in wire.Requests){Assert.That(request.Headers.SingleOrDefault(h=>h.Name=="X-Run-Claim-Version")?.Value,Is.EqualTo(RunCompleteClaimReceipt.Version));Assert.That(request.Headers.Single(h=>h.Name=="Idempotency-Key").Value,Is.EqualTo(op.IdempotencyKey));Assert.That(request.BodyJson,Is.EqualTo(op.BodyJson));Assert.That(request.EndpointPath,Is.EqualTo(op.EndpointPath));}
  }
  [Test] public void ServerV2OriginalReceiptCanBeRetainedWithoutDroppingOwnerPayload(){var p=Fixture();var operation=Operation(p);var result=operation.Confirmed(p.ToString());Assert.That(JToken.DeepEquals(LastRail.Auth.GameApiJson.ReadObject(result.AcceptedResponseJson),p),Is.True);Assert.That(result.Confirmed(p.ToString()).AcceptedResponseJson,Is.EqualTo(result.AcceptedResponseJson));}
  [Test] public void UnmodifiedServerFixtureParsesAtWireBoundary(){var p=(JObject)LastRail.Auth.GameApiJson.ReadObject(File.ReadAllText(Path.GetFullPath("../QA/CommanderS1-20260922/run-complete-claim-example-20261019.json")))["response"];var value=RunCompleteClaimReceipt.Read(p.ToString(),(string)p["accountId"],(string)p["runId"],(string)p["rewardPreviewId"],(string)p["commandId"]);Assert.That(JToken.DeepEquals(value.Capture(),p),Is.True);}
  [Test] public void SourceOrderedSettlementAndSqlProgressTimestampRemainValid(){var p=Fixture();var plan=(JArray)p["transactionReceipt"]["rewardPlan"]["rewardLines"];var first=plan[0];first.Remove();plan.Add(first);var g=(JObject)p["owners"]["progress"];g["beforeMutationSequence"]=g["mutationSequence"]=2;g["versionSource"]="STORY_PROGRESS_MUTATION";g["state"]["story"]=new JObject{{"highestStoryProgressId","story-fixture"}};g["state"]["unlocks"]=new JArray(new JObject{{"unlockId","fixture-unlock"},{"unlockedAt",123456}});g["contentHash"]=LastRail.Battle.BDirectAttackInput.Digest(g["state"]).Substring(7);Assert.DoesNotThrow(()=>Operation(p).Confirmed(p.ToString()));}
  [TestCase("account")][TestCase("key")][TestCase("coverage")][TestCase("sequence")][TestCase("hash")][TestCase("receipt")][TestCase("duplicateCurrency")]
  public void RejectsInvalidOwnerOrReceiptBeforeJournalAcceptance(string kind){var p=Fixture();var operation=Operation(p);switch(kind){case "account":p["accountId"]="other";break;case "key":p["commandId"]="other";break;case "coverage":p["owners"]["account"]["coverage"]=new JArray("CURRENCIES");break;case "sequence":p["owners"]["account"]["mutationSequence"]=0;break;case "hash":p["owners"]["progress"]["contentHash"]=new string('0',64);break;case "receipt":p["transactionReceipt"]["rewardTransactionId"]="other";break;case "duplicateCurrency":((JArray)p["owners"]["account"]["currencies"]).Add(p["owners"]["account"]["currencies"][0].DeepClone());break;}Assert.Throws<FormatException>(()=>operation.Confirmed(p.ToString()));}
 }
}



